package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="bus_trip_events") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class BusTripEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="trip_id",nullable=false) BusTrip trip; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id") Student student; @Column(nullable=false,length=30) String eventType; @Column(columnDefinition="TEXT") String details; @Column(name="occurred_at",nullable=false) LocalDateTime occurredAt; }
